import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent cooperation over full history
    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c

    # Immediate end-game exploitation: grab the last round payoffs
    if n >= 99:
        if total_opp_c > total_opp_d:
            return 'D'
        return 'D' if history[-1][1] == 'C' else 'C'

    # Very last stretch: lean into defection if opponent is cooperative overall
    if n >= 93:
        if total_opp_c * 100 >= n * 60:
            return 'D'
        return 'D' if history[-1][1] == 'C' else 'C'

    # Opponent never defected: cooperate but occasionally skim
    if total_opp_d == 0:
        if n >= 25 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Opponent always defects: just defect, with rare probe
    if total_opp_c == 0:
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    # Recent window
    recent = history[-8:]
    opp_c = sum(1 for a, b in recent if b == 'C')
    opp_d = len(recent) - opp_c
    my_c = sum(1 for a, b in recent if a == 'C')

    my_last, opp_last = history[-1]

    # Detect long defection streak recently
    streak = 0
    for a, b in reversed(history):
        if b == 'D':
            streak += 1
        else:
            break

    # If opponent is in a sustained defection streak, punish hard
    if streak >= 4:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if streak >= 2:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if opp_last == 'C':
        # Exploit heavily cooperative opponents in midgame
        if total_opp_c * 100 >= n * 85 and n > 18:
            if rng.random() < 0.18:
                return 'D'
            return 'C'
        # Punish if we've been extracted from too much
        if opp_d >= 3 and opp_c == 0:
            return 'D'
        # If opponent just recovered and we cooperated, keep cooperating
        return 'C'

    # Opponent defected last round: retaliate, but forgiving for friendly opponents
    if total_opp_c * 100 >= n * 75 and opp_c >= 5:
        # Forgive sometimes to avoid endless mutual defection
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    if my_c >= 6 and opp_c >= 6:
        return 'C'

    if rng.random() < 0.08:
        return 'C'
    return 'D'
